#include <stdio.h>

int main(void) {
    for (int i = 1; i <= {n}; i++) {
        printf("%d 是%s\n", i, (i & 1) ? "奇数" : "偶数");
    }
    printf("1 左移 4 格 = %d\n", 1 << 4);
    return 0;
}
